import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.List;
import java.util.stream.Stream;

/**
 * Course helper for 310-126 OOP (do not edit this file): creates the folder of a new Lab or Assignment.
 *
 * Usage, in the root folder of your repo 310-126-oop (same commands in Windows PowerShell and macOS Terminal):
 *   javac NewTask.java          once, makes NewTask.class
 *   java NewTask Lab0           creates Lab0/ from _template/ (PROCESS.md, Run.java, outputs.txt, ai-log/)
 *   java NewTask Assignment1
 *
 * The folder name must be exactly the one announced with the task (e.g. Lab0, Lab1, Assignment1).
 * An existing folder is never changed. NewTask never runs git: commit yourself after filling in PROCESS.md step 1.
 */
public class NewTask {
    static final String TEMPLATE = "_template";

    public static void main(String[] args) throws IOException {
        if (args.length != 1) {
            System.out.println("Usage: java NewTask <folder>    e.g.  java NewTask Lab0   or   java NewTask Assignment1");
            System.exit(2);
        }
        String name = args[0].replaceAll("[/\\\\]+$", "");
        Path root = Path.of("").toAbsolutePath();
        Path template = root.resolve(TEMPLATE);
        if (!Files.isDirectory(template)) {
            System.out.println("NewTask: no " + TEMPLATE + "/ folder in " + root);
            System.out.println("Run this command in the root folder of your repo 310-126-oop (cd .. if you are inside a task folder).");
            System.exit(2);
        }
        if (!name.matches("[A-Za-z][A-Za-z0-9_-]*") || name.equals(TEMPLATE)) {
            System.out.println("NewTask: '" + name + "' is not a valid folder name; use letters and digits only, e.g. Lab0 or Assignment1");
            System.exit(2);
        }
        Path target = root.resolve(name);
        if (Files.exists(target)) {
            System.out.println("NewTask: " + name + "/ already exists; nothing was changed.");
            System.exit(1);
        }
        try (Stream<Path> s = Files.list(root)) {   // warn about a near-duplicate such as lab0 next to Lab0
            List<String> similar = s.map(p -> p.getFileName().toString()).filter(n -> n.equalsIgnoreCase(name)).toList();
            if (!similar.isEmpty()) {
                System.out.println("NewTask: a folder named " + similar.get(0) + "/ already exists (only upper/lower case differs); nothing was changed.");
                System.exit(1);
            }
        }
        copyTree(template, target);
        System.out.println("Created " + name + "/ with:");
        try (Stream<Path> s = Files.walk(target)) {
            s.filter(Files::isRegularFile).sorted().forEach(p -> System.out.println("  " + root.relativize(p).toString().replace('\\', '/')));
        }
        System.out.println();
        System.out.println("Next:  cd " + name + "   fill in step 1 of PROCESS.md   then   git add .   git commit -m \"...\"   git push");
    }

    static void copyTree(Path from, Path to) throws IOException {
        try (Stream<Path> s = Files.walk(from)) {
            for (Path p : s.sorted().toList()) {
                Path dest = to.resolve(from.relativize(p).toString());
                if (Files.isDirectory(p)) {
                    Files.createDirectories(dest);
                } else {
                    Files.copy(p, dest, StandardCopyOption.COPY_ATTRIBUTES);
                }
            }
        }
    }
}
